	["Honored to Revered: dungeons and stones"] = "Honored → Revered: zindanlar ve taşlar",
	-- {area:2057} Scholomance · {area:2279} Stratholme · {quest:5509} Invader's Scourgestones · {npc:11536} Quartermaster Miranda Breechlock · {area:2268} Light's Hope Chapel · {npc:10857} Argent Quartermaster Lightspark · {area:3197} Chillwind Camp · {npc:10856} Argent Quartermaster Hasana · {area:152} Bulwark · {item:22014} Hallowed Brazier
	["Honored to Revered is 12,000: about 2,400 {area:2057} and {area:2279} mobs, fewer with their bosses. Their mobs stop at 11,999 of 12,000 Honored; a boss or a turn-in takes you over. Solo, only Scourgestones, the cauldron deliveries and Araj count: 12,000 is 480 turn-ins, or 4,800 {quest:5509}. Keep the stones you get in the dungeons until their mobs stop counting. Honored opens recipes at all three quartermasters: {npc:11536} at {area:2268}, {npc:10857} at {area:3197}, {npc:10856} at the {area:152}. Also the {item:22014} (133 gold) for the Three Kings of Flame quest."] = "Honored'dan Revered'a 12.000: yaklaşık 2.400 {area:2057} ve {area:2279} yaratığı, boss'larıyla daha az. Yaratıkları Honored'ın 12.000'inin 11.999'unda durur; bir boss ya da bir teslim seni aşırır. Tek başına yalnızca Scourgestone'lar, kazan teslimatları ve Araj sayılır: 12.000, 480 teslim ya da 4.800 {quest:5509} eder. Zindanlarda aldığın taşları, yaratıkları saymayı bırakana kadar sakla. Honored, üç levazımcıda da tarifleri açar: {area:2268} şapelinde {npc:11536}, {area:3197} kampında {npc:10857}, {area:152} surlarında {npc:10856}. Ayrıca Three Kings of Flame görevi için {item:22014} (133 altın).",
	-- {item:19446} Formula: Enchant Bracer - Mana Regeneration
	["{item:19446}, 3 gold"] = "{item:19446}, 3 altın",
	-- {item:19216} Pattern: Argent Boots · {skill:197} Tailoring
	["{item:19216} ({skill:197}), 2 gold 20 silver"] = "{item:19216} ({skill:197}), 2 altın 20 gümüş",
	-- {item:19328} Pattern: Dawn Treaders · {skill:165} Leatherworking
	["{item:19328} ({skill:165}), 2 gold 20 silver"] = "{item:19328} ({skill:165}), 2 altın 20 gümüş",
	-- {item:19203} Plans: Girdle of the Dawn · {skill:164} Blacksmithing
	["{item:19203} ({skill:164}), 2 gold 20 silver"] = "{item:19203} ({skill:164}), 2 altın 20 gümüş",
	-- {item:13482} Recipe: Transmute Air to Fire · {skill:171} Alchemy
	["{item:13482} ({skill:171}), 1 gold 50 silver"] = "{item:13482} ({skill:171}), 1 altın 50 gümüş",
	-- {item:19442} Formula: Powerful Anti-Venom · {skill:129} First Aid
	["{item:19442} ({skill:129}), 10 gold"] = "{item:19442} ({skill:129}), 10 altın",

	-- Step 11: Mantles of the Dawn
	-- {npc:11536} Quartermaster Miranda Breechlock · {quest:5504} Mantles of the Dawn · {faction:529} Argent Dawn · {item:18173} Shadow Mantle of the Dawn · {item:13810} Blessed Sunfruit
	-- plural, as words: Argent Dawn Valor Tokens = {item:12844} Argent Dawn Valor Token
	["At Revered, {npc:11536} takes 10 Argent Dawn Valor Tokens for {quest:5504} (100 reputation). After it, any {faction:529} quartermaster sells the five shoulder enchants for 10 gold each: Flame, Frost, Arcane, Nature and {item:18173}, +5 to that resistance. Revered also opens the {item:13810} and its juice (60 silver) and the Revered recipes."] = "Revered'da {npc:11536}, {quest:5504} için 10 Argent Dawn Valor Token alır (100 itibar). Ondan sonra her {faction:529} levazımcısı beş omuz büyüsünü tanesi 10 altına satar: Flame, Frost, Arcane, Nature ve {item:18173}, o dirence +5. Revered ayrıca {item:13810} ve suyunu (60 gümüş) ve Revered tariflerini açar.",
	-- plural, as words: Argent Dawn Valor Tokens = {item:12844} Argent Dawn Valor Token
	["Argent Dawn Valor Tokens, from the stone turn-ins"] = "Argent Dawn Valor Token, taş teslimlerinden",
	-- {item:18170} Frost Mantle of the Dawn
	["{item:18170}: pick the resistance you need, 10 gold"] = "{item:18170}: ihtiyacın olan direnci seç, 10 altın",
	-- {item:19447} Formula: Enchant Bracer - Healing
	["{item:19447}, 6 gold"] = "{item:19447}, 6 altın",
	-- {item:19217} Pattern: Argent Shoulders · {skill:197} Tailoring
	["{item:19217} ({skill:197}), 4 gold"] = "{item:19217} ({skill:197}), 4 altın",
	-- {item:19329} Pattern: Golden Mantle of the Dawn · {skill:165} Leatherworking
	["{item:19329} ({skill:165}), 4 gold"] = "{item:19329} ({skill:165}), 4 altın",
	-- {item:19205} Plans: Gloves of the Dawn · {skill:164} Blacksmithing
	["{item:19205} ({skill:164}), 4 gold"] = "{item:19205} ({skill:164}), 4 altın",

	-- Step 12: Revered to Exalted
	["Revered to Exalted"] = "Revered → Exalted",
	-- {quest:5508} Corruptor's Scourgestones · {area:2057} Scholomance · {item:13920} Healthy Dragon Scale
	["Revered to Exalted is 21,000: 840 Scourgestone or cauldron turn-ins, or the dungeon bosses with their {quest:5508} (a full {area:2057} clear is about 600). Turn in every stone and {item:13920} you saved."] = "Revered'dan Exalted'a 21.000: 840 Scourgestone ya da kazan teslimi, ya da {quest:5508} ile zindan boss'ları (tam bir {area:2057} temizlemesi yaklaşık 600). Biriktirdiğin her taşı ve {item:13920} eşyasını teslim et.",

	-- Step 13: Chromatic Mantle of the Dawn
	-- {npc:11536} Quartermaster Miranda Breechlock · {quest:5517} Chromatic Mantle of the Dawn
	-- plural, as words: Argent Dawn Valor Tokens = {item:12844} Argent Dawn Valor Token
	["At Exalted, {npc:11536} takes 25 Argent Dawn Valor Tokens for the {quest:5517} (150 reputation): +5 to every resistance, on your shoulders. After it, the quartermasters sell more for 40 gold each."] = "Exalted'da {npc:11536}, {quest:5517} için 25 Argent Dawn Valor Token alır (150 itibar): omuzlarında her dirence +5. Ondan sonra levazımcılar daha fazlasını tanesi 40 altına satar.",
	-- plural, as words: Argent Dawn Valor Tokens = {item:12844} Argent Dawn Valor Token
	["Argent Dawn Valor Tokens"] = "Argent Dawn Valor Token",

	-- No longer in the guide (its English changed or it went away): reuse or delete.
	-- ["{object:2160} starts out Neutral. Take the Commission from {npc:10840} at {area:3197} and wear it: in Classic, Scourgestones only drop while the {quest:5401} trinket is equipped. Forever's Legacy Diplomat perk increases reputation gains."] = "{object:2160} Neutral başlar. Commission'ı {area:3197} kampındaki {npc:10840} adlı NPC'den al ve kuşan: Classic'te Scourgestone'lar yalnızca {quest:5401} trinket'i kuşanılıyken düşer. Forever'ın Legacy Diplomat ayrıcalığı itibar kazancını artırır.",
	-- ["{object:2160} starts out Neutral. Take the Commission from {npc:10839} at {area:152} and wear it: in Classic, Scourgestones only drop while the {quest:5401} trinket is equipped. Forever's Legacy Diplomat perk increases reputation gains."] = "{object:2160} Neutral başlar. Commission'ı {area:152} siperindeki {npc:10839} adlı NPC'den al ve kuşan: Classic'te Scourgestone'lar yalnızca {quest:5401} trinket'i kuşanılıyken düşer. Forever'ın Legacy Diplomat ayrıcalığı itibar kazancını artırır.",
	-- ["Minion's Scourgestones to Friendly"] = "Minion's Scourgestone: Friendly olana kadar",
	-- ["Ghouls and skeletons all over {zone:1422} drop Minion's Scourgestones about half the time; this cluster is dense. Hand them in 20 at a time to any Argent Officer (Pureheart at {area:3197}, Garush at {area:152}, {npc:11039} at {area:2268}). Each turn-in also pays an {item:12844} for the Argent quartermasters."] = "{zone:1422} bölgesinin her yanındaki ghoul ve iskeletler yaklaşık yarı yarıya Minion's Scourgestone düşürür; bu küme yoğun. Onları 20'şer 20'şer herhangi bir Argent Officer'a teslim et ({area:3197} kampında Pureheart, {area:152} siperinde Garush, {area:2268} şapelinde {npc:11039}). Her teslim Argent levazımcıları için bir {item:12844} de kazandırır.",
	-- ["Invader's Scourgestones to Honored"] = "Invader's Scourgestone: Honored olana kadar",
	-- ["Dark Adepts and Shadowmages (level 58-60) drop Invader's Scourgestones here, along with Minion's stones and {item:14047}. Hand Invader's in 10 at a time and Minion's 20 at a time to {npc:11039} at {area:2268}. In Classic both stop giving reputation at Honored."] = "Burada Dark Adept ve Shadowmage yaratıkları (seviye 58-60) Minion's taşları ve {item:14047} ile birlikte Invader's Scourgestone düşürür. Invader's taşlarını 10'ar, Minion's taşlarını 20'şer {area:2268} şapelindeki {npc:11039} adlı NPC'ye teslim et. Classic'te ikisi de Honored'da itibar vermeyi keser.",
	-- ["Corruptor's Scourgestones and dungeons to Revered"] = "Corruptor's Scourgestone ve zindanlar: Revered olana kadar",
	-- ["From Honored on, Corruptor's Scourgestones (one per turn-in) and Scourge kills in {area:2279} and {area:2057} carry the reputation. Corruptor's stones drop from the Scourge bosses there ({npc:1853}, {npc:10433}, Vectus) and from {npc:1852} and Putridius in {zone:1422}. Many dungeon runs pay off faster than any open-world farm."] = "Honored'dan sonra itibarı Corruptor's Scourgestone'lar (teslim başına bir tane) ve {area:2279} ile {area:2057} içindeki Scourge öldürmeleri taşır. Corruptor's taşları oradaki Scourge boss'larından ({npc:1853}, {npc:10433}, Vectus) ve {zone:1422} bölgesindeki {npc:1852} ile Putridius'tan düşer. Çok sayıda zindan koşusu her açık dünya farm'ından daha hızlı sonuç verir.",
	-- ["Run {area:2279} (both wings) and {area:2057}, killing every Scourge you pass."] = "{area:2279} (iki kanadı da) ve {area:2057} koş, geçtiğin her Scourge'u öldür.",
	-- ["{faction:529} to Exalted"] = "{faction:529}: Exalted olana kadar",
	-- ["Keep running {area:2279} and {area:2057} and turning in every {item:12843} at {area:2268} until Exalted."] = "Exalted olana kadar {area:2279} ve {area:2057} koşmaya ve her {item:12843} eşyasını {area:2268} şapelinde teslim etmeye devam et.",
}
